import os, json, re

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

# Parse all input/output grids from the log
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print(f"Total grids loaded: {list(G.keys())}")
for k in G:
    print(f"{k}: shape={len(G[k])}x{len(G[k][0]) if G[k] else 0}")

# Count non-zero cells
demo1_input = [[0, 7, 0], [7, 7, 7], [0, 7, 0]]
demo2_input = [[0, 0, 6], [0, 6, 0], [6, 0, 0]]

def count_nonzero(grid, val):
    count = sum(1 for row in grid for x in row if x == val)
    return count

print(f"Demo 1, count of 7: {count_nonzero(demo1_input, 7)}")
print(f"Demo 2, count of 6: {count_nonzero(demo2_input, 6)}")

