# Count value in output blocks
def count_in_block(m, row_offset, col_offset, val):
    count = 0
    for i in range(3):
        for j in range(3):
            if m[row_offset + i][col_offset + j] == val:
                count += 1
    return count

print("\nDemo 1 block patterns:")
for r in range(3):
    for c in range(3):
        if demo1_input[r][c] == 7:
            cnt = count_in_block(demo1_output, r*3, c*3, 7)
            print(f"  Block ({r},{c}) has {cnt} sevens")

