# Fix the mask extraction - block should be from output_grid[row*3:i*3+3, col*3:j*3+3]

def get_block_mask(input_grid, output_grid, val, block_pos):
    """Get which positions in the 3x3 block at block_pos have the value."""
    r, c = block_pos
    mask = [[0]*3 for _ in range(3)]
    for i in range(3):
        for j in range(3):
            pos_i, pos_j = r*3 + i, c*3 + j
            if output_grid[pos_i][pos_j] == val:
                mask[i][j] = 1
    return mask

