def rot90(grid):
    return list(zip(*grid[::-1]))

def rot180(grid):
    return rot90(rot90(grid))

def rot270(grid):
    return rot90(rot90(rot90(grid)))

def mirror_h(grid):
    return [row[::-1] for row in grid]

def mirror_v(grid):
    return grid[::-1]

def transpose(grid):
    return list(zip(*grid))

def complement(grid):
    return [[1-x for x in row] for row in grid]

# Check relationships
d1_input = [[0, 1, 0], [1, 1, 1], [0, 1, 0]]  # treating 7 as 1
d1_mask = [[1, 0, 1], [0, 0, 0], [1, 0, 1]]
