# Build the full output

# Block pattern (where to put the value 3 in each 3x3 block)
block_pattern = [[1, 1, 0], [0, 0, 1], [1, 0, 1]]

test_input = [[0, 0, 3], [3, 3, 0], [0, 3, 0]]

# Initialize empty 9x9 output
output = [[0]*9 for _ in range(9)]

# For each non-zero input cell, apply the block pattern
for r in range(3):
    for c in range(3):
        if test_input[r][c] == 3:
            block_r = r * 3
            block_c = c * 3
            for i in range(3):
